<?php
use yii\helpers\Html;
$this->title=$model->name;
?>
<div class="d-flex align-items-start justify-content-between gap-3 mb-3"><div><h1 class="h4 mb-1"><?= Html::encode($model->name) ?></h1><p class="text-body-secondary mb-0"><?= Html::encode($model->positionGroup->title??'') ?> · revision <?= $model->revision_no ?> · <?= Html::encode($model->statusLabel) ?></p></div><div class="d-flex flex-wrap gap-2"><?= Html::a('กลับรายการ',['index'],['class'=>'btn btn-outline-secondary']) ?><?php if($model->status==='draft'): ?><?= Html::a('แก้ไข',['form','id'=>$model->id],['class'=>'btn btn-outline-primary']) ?><?= Html::a('เพิ่มข้อประเมิน',['item','template_id'=>$model->id],['class'=>'btn btn-primary']) ?><?= Html::beginForm(['activate','id'=>$model->id],'post').Html::submitButton('เปิดใช้งาน',['class'=>'btn btn-success']).Html::endForm() ?><?php else: ?><?= Html::a('สร้าง Revision ใหม่',['revision','id'=>$model->id],['class'=>'btn btn-primary']) ?><?php endif ?></div></div>
<section class="card bg-body border shadow-sm overflow-hidden"><?php if(!$model->items): ?><div class="text-center p-5"><h2 class="h5">ยังไม่มีข้อประเมิน</h2><p class="text-body-secondary">เพิ่มข้อประเมินและคะแนนเต็มก่อนเปิดใช้งาน</p></div><?php else: ?><table class="table align-middle mb-0"><thead><tr><th class="text-center">ลำดับ</th><th>หมวด</th><th>ข้อประเมิน</th><th class="text-end">คะแนนเต็ม</th><th class="text-end">จัดการ</th></tr></thead><tbody><?php foreach($model->items as $item): ?><tr><td class="text-center"><?= $item->sequence ?></td><td><?= Html::encode($item->category) ?></td><td><?= Html::encode($item->question) ?></td><td class="text-end"><?= number_format($item->max_score,2) ?></td><td class="text-end"><?php if($model->status==='draft'): ?><?= Html::a('แก้ไข',['item','template_id'=>$model->id,'id'=>$item->id],['class'=>'btn btn-sm btn-outline-secondary']) ?><?php endif ?></td></tr><?php endforeach ?></tbody><tfoot><tr><th colspan="3" class="text-end">คะแนนเต็มรวม</th><th class="text-end"><?= number_format(array_sum(array_map(fn($i)=>(float)$i->max_score,$model->items)),2) ?></th><th></th></tr></tfoot></table><?php endif ?></section>
